/**
 * Generate a synthetic benchmark/demo graph as CSVs + a manifest under
 * `out_dir`, in bounded memory. Load the result with [`kglite_load_file`]
 * pointed at `out_dir` — the C-side handle on `kglite.graphgen(...)`, the
 * "hello, query a graph" data source for a fresh binding.
 *
 * `zipf` != 0 uses a Zipf degree distribution (high-degree hubs) with
 * exponent `zipf_exp`; `zipf` == 0 uses uniform degree.
 *
 * On success `out_stats_json` is set to an owned `{"nodes": N, "edges": M}`
 * string — free via [`kglite_free_string`](crate::kglite_free_string).
 *
 * # Safety
 *
 * `out_dir` must be a null-terminated UTF-8 path; `out_stats_json` a valid
 * writable `*const c_char` slot; `out_error_msg` null or a valid slot.
 */

KgliteStatusCode kglite_graphgen_to_dir(uint64_t persons,
                                        uint64_t knows_per,
                                        uint64_t seed,
                                        uint8_t zipf,
                                        double zipf_exp,
                                        const char *out_dir,
                                        const char **out_stats_json,
                                        const char **out_error_msg);

/**
 * Build a graph declaratively from a blueprint file + a directory of
 * CSVs — the C-side handle on the wheel's `from_blueprint`. Loads the
 * JSON/YAML blueprint at `blueprint_path`, builds into a fresh graph
 * reading CSVs relative to `csv_dir`, and returns the populated graph.
 *
 * On success `out_graph` is set to a `KgliteGraph*` (free via
 * [`kglite_graph_free`] or hand to [`kglite_session_new`](crate::kglite_session_new)),
 * and `out_report_json` to an owned
 * `{"nodes_by_type":{..},"edges_by_type":{..},"warnings":[..],"errors":[..],"provisional_purged":N,
 * "diagnostics":[{"group":..,"kind":..,"message":..}],"summary":{"<group>":N}}`
 * string — free via [`kglite_free_string`](crate::kglite_free_string).
 * `diagnostics` classifies every `warnings` entry (same order); `group` is one of
 * `declarations`, `stubs`, `data_shape`, `data_quality`, `cosmetic`, most severe first,
 * and `summary` counts the non-empty groups.
 *
 * # Safety
 *
 * `blueprint_path` / `csv_dir` must be null-terminated UTF-8 paths;
 * `out_graph` / `out_report_json` valid writable slots; `out_error_msg`
 * null or a valid slot.
 */

KgliteStatusCode kglite_blueprint_build(const char *blueprint_path,
                                        const char *csv_dir,
                                        struct KgliteGraph **out_graph,
                                        const char **out_report_json,
                                        const char **out_error_msg);

/**
 * Save a graph to a `.kgl` file with an explicit durability choice.
 *
 * `fsync` != 0 is exactly [`kglite_save_graph`]: mode-aware (disk dir vs
 * in-memory `.kgl`), atomic temp+rename, and the file + parent directory
 * are flushed to stable storage before returning — durable across power
 * loss, at the cost of fsync latency.
 *
 * `fsync` == 0 is the fast, **non-durable** opt-out: same mode-aware
 * atomic rename (never a torn file) but the fsync barrier is skipped, so
 * the bytes may not survive an OS/power crash. Use it only for bulk or
 * throwaway saves where you'll re-save or can rebuild.
 *
 * # Safety
 *
 * `graph` must be a valid handle; `path` a null-terminated UTF-8 path;
 * `out_error_msg` null or a valid slot.
 */

KgliteStatusCode kglite_save_graph_durable(struct KgliteGraph *graph,
                                           const char *path,
                                           uint8_t fsync,
                                           const char **out_error_msg);

/**
 * Serialize a graph to an in-memory `.kgl` byte buffer (no file). On
 * success `*out_buf` / `*out_len` describe an owned buffer the caller
 * MUST free with [`kglite_free_bytes`]. Pair with
 * [`kglite_graph_from_bytes`] to round-trip a graph through bytes (IPC,
 * object storage, …).
 *
 * # Safety
 *
 * `graph` valid; `out_buf` a valid `*mut u8` slot; `out_len` a valid
 * `usize` slot; `out_error_msg` null or valid.
 */

KgliteStatusCode kglite_graph_to_bytes(struct KgliteGraph *graph,
                                       uint8_t **out_buf,
                                       uintptr_t *out_len,
                                       const char **out_error_msg);

/**
 * Free a byte buffer returned by [`kglite_graph_to_bytes`]. Pass the
 * same `buf` / `len` pair. Null `buf` is a no-op.
 *
 * # Safety
 *
 * `buf` / `len` must be a pair previously returned by
 * [`kglite_graph_to_bytes`] and not yet freed.
 */
 void kglite_free_bytes(uint8_t *buf, uintptr_t len);

/**
 * Load a graph from an in-memory `.kgl` byte buffer — the inverse of
 * [`kglite_graph_to_bytes`].
 *
 * # Safety
 *
 * `data` / `len` must describe a readable buffer; `out_graph` a valid
 * writable slot; `out_error_msg` null or a valid slot.
 */

KgliteStatusCode kglite_graph_from_bytes(const uint8_t *data,
                                         uintptr_t len,
                                         struct KgliteGraph **out_graph,
                                         const char **out_error_msg);

/**
 * Compute a JSON schema overview of a graph: node types (count +
 * property types), connection types (endpoints + property names),
 * indexes, and total node/edge counts. The C-side handle on the
 * agent-facing schema — call it right after load / build / from_bytes
 * to learn a graph's shape before querying.
 *
 * On success `out_json` is set to an owned JSON object — free via
 * [`kglite_free_string`](crate::kglite_free_string). Operates on a graph
 * handle (before it is moved into a session).
 *
 * # Safety
 *
 * `graph` must be a valid handle; `out_json` a valid writable slot;
 * `out_error_msg` null or a valid slot.
 */

KgliteStatusCode kglite_compute_schema_json(struct KgliteGraph *graph,
                                            const char **out_json,
                                            const char **out_error_msg);

/**
 * Open the graph at `path` as a durable session: take the single-writer
 * lease, open (or create) the graph, recover from the write-ahead log, and
 * return a session whose commits are logged at the chosen level.
 *
 * This is the one-call open for a binding that serves a path. It is the
 * composition `kglite_writer_lease_acquire` → `kglite_open_or_create_graph_in_mode`
 * → `kglite_session_new`, with the log opened and replayed in the right
 * order, so use it instead of that sequence whenever commits must survive a
 * crash.
 *
 * `options_json` is null, `"{}"`, or a JSON object; an unknown key is
 * `KGLITE_STATUS_CODE_INVALID_ARGUMENT`, so a misspelt option never silently
 * does nothing. Keys:
 *
 * - `"storage"`: `"memory"` (alias `"default"`), `"mapped"` or `"disk"`.
 *   Creates a missing path in that mode and converts an existing graph to it
 *   (reported in `converted_from`). Absent: an existing graph keeps the mode
 *   its checkpoint recorded and a created one is `"memory"`.
 * - `"durability"`: `"full"` (default; every commit is on stable storage when
 *   the call returns), `"normal"` (the log is written but flushed only by
 *   [`kglite_session_sync`] or a checkpoint) or `"off"` (no log; changes
 *   persist only through [`kglite_session_checkpoint`], [`kglite_session_save`]
 *   or [`kglite_session_close`]). A disk-mode graph has no logical log: left
 *   at the default it runs at `"off"` and reports `degraded_from`; asked for
 *   explicitly it is an error.
 * - `"lock_timeout_ms"`: how long to retry a contended lease. `0` (default)
 *   fails fast. **`-1` takes no lease and opens read-only**: the last
 *   checkpoint is loaded with nothing created, converted, logged or written,
 *   every write is `KGLITE_STATUS_CODE_READ_ONLY`, and `"storage"`,
 *   `"create_if_missing"` and a logging `"durability"` are refused.
 * - `"valid_time_default"`: `"today"` (default), `"all"` or a `YYYY-MM-DD`
 *   date; the instant unprefixed statements read on a graph that declares
 *   validity intervals.
 * - `"auto_checkpoint_wal_mib"`: non-negative integer, default `16`; `0`
 *   disables it. A durable session whose log outgrows this many MiB (and is at
 *   least as large as its checkpoint) folds it into the checkpoint with an
 *   online checkpoint, run **inline** on the thread of the commit that crossed
 *   the bound, once that commit is published: other threads keep committing
 *   during the file write, but that one call takes the checkpoint's time.
 *   Without it the log grows until `kglite_session_checkpoint` or close.
 * - `"create_if_missing"`: boolean, default `false`. A missing path is
 *   `KGLITE_STATUS_CODE_FILE_NOT_FOUND` unless this is true, so a typo'd path
 *   never becomes an empty database.
 *
 * On success `out_info_json` (nullable) is an owned JSON object: `path`,
 * `read_only`, `created`, `storage` (the mode now running), `durability`
 * (the level actually in force), `degraded_from` (the requested level when it
 * was degraded to `"off"`, else null), `converted_from` (null when nothing was
 * converted) and `advisories` (`[{code, message, affected}]`, such as a
 * quarantined log or a saved torn tail an operator should read). Free it with
 * [`kglite_free_string`](crate::kglite_free_string).
 *
 * A contended lease returns `KGLITE_STATUS_CODE_WRITER_LEASE_HELD`; the holder
 * is in the message and, as JSON, in `kglite_last_error_details_json`.
 *
 * **Ownership.** The session owns the lease. [`kglite_session_free`] releases
 * it (the log already holds every logged commit); [`kglite_session_close`]
 * first checkpoints unsaved changes, then releases it. A binding ties one of
 * them to its deterministic teardown: a never-freed session holds the lease
 * until the process exits.
 *
 * Mutations through [`kglite_session_execute_mut`] and the `_opts`/`_ex`
 * variants, `kglite_session_execute_mut_batch`, `kglite_create_edges_batch`
 * and ontology declaration are logged. Schema, text-index and embedding
 * ingest calls bypass the log and are refused with
 * `KGLITE_STATUS_CODE_DURABILITY_FAILED` on a session whose durability is not
 * `"off"`; checkpoint, or open with `"durability":"off"`, to use them.
 *
 * # Errors
 *
 * - `KGLITE_STATUS_CODE_NULL_POINTER` — `path` or `out_session` is null
 * - `KGLITE_STATUS_CODE_INVALID_UTF8` — `path` or `options_json` isn't UTF-8
 * - `KGLITE_STATUS_CODE_INVALID_ARGUMENT` — malformed or unknown option, or a
 *   conversion that cannot happen in place
 * - `KGLITE_STATUS_CODE_FILE_NOT_FOUND` — missing path without `create_if_missing`
 * - `KGLITE_STATUS_CODE_WRITER_LEASE_HELD` — another writer holds the path
 * - `KGLITE_STATUS_CODE_FILE_FORMAT` / `KGLITE_STATUS_CODE_FILE_IO` — as
 *   [`kglite_load_file`](crate::kglite_load_file); a log that cannot be
 *   replayed is `FILE_IO`
 *
 * # Safety
 *
 * `path` must be a null-terminated UTF-8 string; `options_json` null or the
 * same; `out_session` a valid writable slot; `out_info_json` and
 * `out_error_msg` null or valid writable slots.
 */

KgliteStatusCode kglite_open_session(const char *path,
                                     const char *options_json,
                                     struct KgliteSession **out_session,
                                     const char **out_info_json,
                                     const char **out_error_msg);

/**
 * Flush the write-ahead log to stable storage — the power-safe point at
 * durability `"normal"` (a no-op at `"full"`, where every commit already is).
 *
 * # Errors
 *
 * - `KGLITE_STATUS_CODE_NULL_POINTER` — `session` is null
 * - `KGLITE_STATUS_CODE_READ_ONLY` — the session is read-only
 * - `KGLITE_STATUS_CODE_NOT_DURABLE` — the session has no write-ahead log
 *   (not opened by [`kglite_open_session`], or durability `"off"`); use
 *   [`kglite_session_checkpoint`] instead
 * - `KGLITE_STATUS_CODE_DURABILITY_FAILED` — the flush failed, or direct
 *   writes have left the log not describing the graph
 *
 * # Safety
 *
 * `session` must be a valid session pointer not yet freed; `out_error_msg`
 * null or a valid writable slot.
 */

KgliteStatusCode kglite_session_sync(const struct KgliteSession *session,
                                     const char **out_error_msg);

/**
 * Write a checkpoint of the session to the path it was opened from, unless
 * nothing changed since this handle's last one. The first call always writes.
 * A durable session's checkpoint also truncates its log.
 *
 * `out_written` (nullable) is set to 1 when a file was written and 0 when the
 * graph was unchanged; `out_version` (nullable) to the graph version
 * checkpointed. A failed write changes neither and can be retried.
 *
 * # Errors
 *
 * - `KGLITE_STATUS_CODE_NULL_POINTER` — `session` is null
 * - `KGLITE_STATUS_CODE_READ_ONLY` — the session is read-only
 * - `KGLITE_STATUS_CODE_INVALID_ARGUMENT` — the session was not opened by
 *   [`kglite_open_session`] (use [`kglite_session_save`] with a path), or is closed
 * - `KGLITE_STATUS_CODE_FILE_IO` — the write failed
 *
 * # Safety
 *
 * `session` must be a valid session pointer not yet freed; the out pointers
 * null or valid writable slots.
 */

KgliteStatusCode kglite_session_checkpoint(struct KgliteSession *session,
                                           uint8_t *out_written,
                                           uint64_t *out_version,
                                           const char **out_error_msg);

/**
 * Checkpoint unsaved changes, then release the writer lease. Idempotent: a
 * second call returns `KGLITE_STATUS_CODE_OK` and does nothing.
 *
 * Mirrors the Node binding's `close()`. A read-only session, and a session not
 * opened by [`kglite_open_session`], skips the checkpoint. If the checkpoint
 * fails the call returns `KGLITE_STATUS_CODE_FILE_IO` and the session stays
 * open with the lease held, so the caller can retry rather than lose the
 * changes. After a successful close every write is refused
 * (`KGLITE_STATUS_CODE_INVALID_ARGUMENT`, "this session is closed"); reads of
 * the in-memory graph still work. The handle is **not** freed — call
 * [`kglite_session_free`] afterwards. Do not call it concurrently with writes
 * on the same session.
 *
 * # Safety
 *
 * `session` must be a valid session pointer not yet freed; `out_error_msg`
 * null or a valid writable slot.
 */
 KgliteStatusCode kglite_session_close(struct KgliteSession *session, const char **out_error_msg);

/**
 * Declare the session graph's ontology from a JSON document.
 *
 * `ontology_json` uses the same dialect as the Python wheel's
 * `define_ontology` (`classes`, `relationships`, `closed_labels`,
 * `enforcement`, `version`), parsed by the same core function. Stored data is
 * checked against the declaration first. An `error`-level rule that stored
 * data already breaks refuses the declaration: nothing changes and the
 * previous ontology stays.
 *
 * On success `out_warnings_json` is an owned JSON array of strings (the
 * `warn`-level findings; empty when there are none). On an
 * `KGLITE_STATUS_CODE_ONTOLOGY_VIOLATION` refusal it is an owned JSON array
 * of report objects `{rule, entity, entity_type, property, count}`,
 * `out_error_msg` carries the readable report, and
 * [`kglite_last_error_details_json`](crate::details::kglite_last_error_details_json)
 * returns the headline fields with the same report. On any other failure it is
 * null. `out_warnings_json` may be null when the caller wants neither. Free
 * both with [`kglite_free_string`](crate::kglite_free_string).
 *
 * # Errors
 *
 * - `KGLITE_STATUS_CODE_NULL_POINTER` — `session` or `ontology_json` is null.
 * - `KGLITE_STATUS_CODE_INVALID_UTF8` — `ontology_json` is not valid UTF-8.
 * - `KGLITE_STATUS_CODE_INVALID_ARGUMENT` — the JSON did not parse, is not in
 *   the dialect, or the ontology is locked by the operator.
 * - `KGLITE_STATUS_CODE_ONTOLOGY_VIOLATION` — stored data breaks an
 *   `error`-level rule of the declaration.
 *
 * On a durable session from [`kglite_open_session`](crate::kglite_open_session)
 * the declaration is write-ahead logged. On a session without a log it is not
 * durable until [`kglite_session_save`](crate::kglite_session_save).
 *
 * # Safety
 *
 * `session` must be a valid handle from
 * [`kglite_session_new`](crate::kglite_session_new); `ontology_json` a
 * null-terminated UTF-8 string; `out_warnings_json` and `out_error_msg` null
 * or valid writable slots.
 */

KgliteStatusCode kglite_session_define_ontology(const struct KgliteSession *session,
                                                const char *ontology_json,
                                                const char **out_warnings_json,
                                                const char **out_error_msg);

/**
 * Remove the session graph's declared ontology.
 *
 * A no-op success when none is declared. Refused with
 * `KGLITE_STATUS_CODE_INVALID_ARGUMENT` when the operator locked the
 * ontology.
 *
 * # Errors
 *
 * - `KGLITE_STATUS_CODE_NULL_POINTER` — `session` is null.
 * - `KGLITE_STATUS_CODE_INVALID_ARGUMENT` — the ontology is locked.
 *
 * # Safety
 *
 * `session` must be a valid handle from
 * [`kglite_session_new`](crate::kglite_session_new); `out_error_msg` null or
 * a valid writable slot.
 */

KgliteStatusCode kglite_session_clear_ontology(const struct KgliteSession *session,
                                               const char **out_error_msg);

/**
 * Take the cross-process single-writer lease for a graph path.
 *
 * **The contract: any caller that may `save` to a path must hold this lease
 * across the whole read-modify-save interval. Readers need none.** The
 * window that loses a writer's work is open-to-save, not save itself — two
 * processes that both load a graph, both mutate, and both save produce two
 * complete snapshots, and the second one published wins outright, silently —
 * locking at save time is already too late. Acquire before the open, free
 * after the save.
 *
 * The lease is a pair of sidecar files next to `path` (`<path>.lock` holds
 * the OS lock, `<path>.lock-owner` records who has it). The OS releases the
 * lock when the holding process exits — including on a crash — so a lock
 * file left behind is not a stale lease, and deleting it does not release
 * anything.
 *
 * # Arguments
 *
 * - `path` (in, borrowed): UTF-8 graph path, null-terminated. The path need
 *   not exist yet; a caller creating a new graph takes the lease first.
 * - `timeout_ms` (in): how long to keep retrying a contended lease. **`0`
 *   is fail-fast** — return immediately if someone else holds it, because a
 *   blocked-for-30s open is a worse failure than a clear error. A caller that
 *   wants to queue passes a budget instead.
 * - `out_lease` (out, owned): set to the lease handle on success; the caller
 *   MUST free it with [`kglite_writer_lease_free`]. Null on failure.
 * - `out_error_msg` (out, owned): owned error message on failure (free via
 *   [`kglite_free_string`](crate::kglite_free_string)); null on success. On
 *   `KGLITE_STATUS_CODE_WRITER_LEASE_HELD` the message names the holding
 *   process (pid, and when it took the lease).
 *
 * # Errors
 *
 * - `KGLITE_STATUS_CODE_NULL_POINTER` — `path` or `out_lease` is null
 * - `KGLITE_STATUS_CODE_INVALID_UTF8` — `path` isn't valid UTF-8
 * - `KGLITE_STATUS_CODE_WRITER_LEASE_HELD` — someone else holds it; the
 *   message names them. Retriable as-is.
 * - `KGLITE_STATUS_CODE_FILE_IO` / `KGLITE_STATUS_CODE_FILE_NOT_FOUND` — the lock sidecar
 *   could not be created (unwritable or missing parent directory)
 *
 * # Safety
 *
 * `path` must be a null-terminated UTF-8 string; `out_lease` a valid
 * writable `*mut KgliteWriterLease` slot; `out_error_msg` null or a valid
 * writable slot.
 */

KgliteStatusCode kglite_writer_lease_acquire(const char *path,
                                             uint64_t timeout_ms,
                                             struct KgliteWriterLease **out_lease,
                                             const char **out_error_msg);

/**
 * [`kglite_writer_lease_acquire`], plus the holder as **JSON** rather than
 * only inside the message's prose.
 *
 * A binding that wants to surface the holding pid — the Java wrapper's
 * `holder()`, an operator dashboard, a retry policy that backs off longer for
 * a lease taken hours ago — otherwise has to regex a sentence written for
 * humans, and re-parse it every time the wording improves.
 *
 * Additive: `kglite_writer_lease_acquire` is unchanged and stays supported.
 * New callers should prefer this one.
 *
 * # Arguments
 *
 * Identical to [`kglite_writer_lease_acquire`], plus:
 *
 * - `out_holder_json` (out, owned): on
 *   `KGLITE_STATUS_CODE_WRITER_LEASE_HELD`, an owned JSON object (free via
 *   [`kglite_free_string`](crate::kglite_free_string)); null on every other
 *   outcome, including success. May itself be null if the caller does not
 *   want the detail. The object is:
 *
 *   ```json
 *   {"pid": 4711, "since": "2026-08-15T09:12:03+02:00",
 *    "self": false, "message": "…the same prose out_error_msg carries…"}
 *   ```
 *
 *   `pid` and `since` are `null` when the holder's record could not be read
 *   — it is published just *after* the lock is taken, so a contender losing
 *   a startup race can see an empty one. `self` is true when the holder is
 *   the calling process itself (an un-closed handle in the caller's own
 *   code, not another deployment), which is a different remedy and so is
 *   reported as its own field rather than left for a pid comparison the
 *   caller may forget to make.
 *
 * # Safety
 *
 * As [`kglite_writer_lease_acquire`]; `out_holder_json` must be null or a
 * valid writable slot.
 */

KgliteStatusCode kglite_writer_lease_acquire_ex(const char *path,
                                                uint64_t timeout_ms,
                                                struct KgliteWriterLease **out_lease,
                                                const char **out_holder_json,
                                                const char **out_error_msg);

/**
 * Release a writer lease and free its handle. Idempotent on null (no-op).
 *
 * This is the whole release protocol: there is no separate "unlock" call.
 * A handle that is never freed holds the lease for the life of the process —
 * the C-side shape of the Rust `Drop` that backs it — so a binding should
 * tie this call to its own deterministic teardown (`close()`, try-with-
 * resources, `defer`), not to a finalizer that may never run.
 *
 * # Safety
 *
 * `lease` must be either null or a pointer previously returned by
 * [`kglite_writer_lease_acquire`] or [`kglite_writer_lease_acquire_ex`] and
 * not yet freed. Calling twice on the same pointer is UB.
 */
 void kglite_writer_lease_free(struct KgliteWriterLease *lease);

/**
 * Open the graph at `path`, creating it when the path is absent, honouring
 * `mode` on **both** branches: a missing path is created in it, and an
 * existing graph that came back in a different mode is converted to it.
 *
 * This is the entry point for a binding that took a mode from *its* user
 * (the servers' `--storage`, the wheel's `storage=`). Pass `mode` null to
 * leave the decision to the graph: an existing checkpoint reopens in the
 * mode it recorded, and a missing path is an error rather than a silent
 * creation in some default. That asymmetry is deliberate — a mode argument
 * that also silently converted an existing graph would undo what the
 * checkpoint recorded, and a null one that silently created a graph would
 * turn a typo'd path into an empty database.
 *
 * A conversion is *reported*, through `out_converted_from`, never performed
 * silently — a silent conversion is as hard to notice as a silently ignored
 * flag. Conversions with no in-place transition (either disk direction) fail
 * with the reason and the alternative named.
 *
 * This function makes a lifecycle decision, **not** a write-ownership
 * promise. A caller that may later save to `path` must hold
 * [`kglite_writer_lease_acquire`]'s lease across the read-modify-save
 * interval; a read-only caller should not take one.
 *
 * # Arguments
 *
 * - `path` (in, borrowed): UTF-8 graph path (a `.kgl` file or a disk-graph
 *   directory), null-terminated.
 * - `mode` (in, borrowed, may be null): `"memory"` (alias `"default"`),
 *   `"mapped"`, or `"disk"` — the same mode vocabulary as
 *   [`kglite_graph_new_in_mode`](crate::kglite_graph_new_in_mode) and
 *   Python's `storage=`. **Null means unspecified**, the C spelling of "no
 *   mode argument at all".
 * - `out_graph` (out, owned): the opened / created graph on success (free
 *   via [`kglite_graph_free`](crate::kglite_graph_free), or hand to
 *   [`kglite_session_new`](crate::kglite_session_new)); null on failure.
 * - `out_converted_from` (out, owned, may be null): set to the mode the
 *   graph was in *before* an explicit `mode` converted it (`"memory"` /
 *   `"mapped"` / `"disk"`) — free via
 *   [`kglite_free_string`](crate::kglite_free_string). **Null when nothing
 *   was converted**, which is every open that already matched, every
 *   creation, and every unspecified-mode open.
 * - `out_error_msg` (out, owned): owned error message on failure; null on
 *   success.
 *
 * # Errors
 *
 * - `KGLITE_STATUS_CODE_NULL_POINTER` — `path` or `out_graph` is null
 * - `KGLITE_STATUS_CODE_INVALID_UTF8` — `path` / `mode` isn't valid UTF-8
 * - `KGLITE_STATUS_CODE_FILE_NOT_FOUND` — the path is absent and `mode` was null,
 *   so there was no mode to create it in
 * - `KGLITE_STATUS_CODE_INVALID_ARGUMENT` — unknown mode string, or a conversion
 *   that cannot happen in place (either disk direction)
 * - `KGLITE_STATUS_CODE_FILE_FORMAT` / `KGLITE_STATUS_CODE_FILE_IO` — as
 *   [`kglite_load_file`](crate::kglite_load_file)
 *
 * # Safety
 *
 * `path` must be a null-terminated UTF-8 string; `mode` null or the same;
 * `out_graph` a valid writable `*mut KgliteGraph` slot; `out_converted_from`
 * and `out_error_msg` null or valid writable slots.
 */

KgliteStatusCode kglite_open_or_create_graph_in_mode(const char *path,
                                                     const char *mode,
                                                     struct KgliteGraph **out_graph,
                                                     const char **out_converted_from,
                                                     const char **out_error_msg);

/**
 * Return the column names as a JSON array string:
 * `["col1", "col2", ...]`.
 *
 * The returned string is OWNED by the caller and must be freed
 * via [`kglite_free_string`](crate::kglite_free_string). Returns
 * null on serialization failure (shouldn't happen — column names
 * are always serializable).
 *
 * # Safety
 *
 * `result` must be null or a live pointer returned by a kglite query
 * function. It must not be freed while this call is running.
 */
 const char *kglite_cypher_result_columns_json(const struct KgliteCypherResult *result);

/**
 * Return all rows as a JSON array of objects keyed by column
 * name: `[{"col1": v1, "col2": v2}, ...]`.
 *
 * Cell values are **natural** JSON (`2`, `"x"`, `[..]`, `{..}`) via
 * [`kglite_value_to_json`](kglite::api::param::kglite_value_to_json) —
 * not serde's externally-tagged enum encoding — so a binding parses
 * `{"n": 2}`, not `{"n": {"Int64": 2}}`. A date is a string, a NaN or infinite
 * float is `null`, and a point is `{"latitude", "longitude"}` unless the
 * producing session chose
 * [`kglite_session_set_result_encoding`](crate::kglite_session_set_result_encoding)
 * `Tagged`, which renders them as the one-key tags a query parameter accepts.
 *
 * This materializes the entire JSON blob in memory. For a large result
 * open a [`KgliteCursor`](crate::KgliteCursor) with
 * [`kglite_session_cursor_open`](crate::kglite_session_cursor_open) and pull
 * it a batch at a time instead.
 *
 * The returned string is OWNED by the caller and must be freed
 * via [`kglite_free_string`](crate::kglite_free_string). Returns
 * null on serialization failure.
 *
 * # Safety
 *
 * `result` must be null or a live pointer returned by a kglite query
 * function. It must not be freed while this call is running.
 */
 const char *kglite_cypher_result_rows_json(const struct KgliteCypherResult *result);

/**
 * Return execution diagnostics as owned JSON, including actual retrieval routes.
 * A `PROFILE` query's diagnostics also carry a `profile` array, one
 * `{"clause", "rows_in", "rows_out", "elapsed_us"}` object per executed clause;
 * the key is absent otherwise.
 * A live result with no diagnostics returns the JSON string `null`. A null
 * handle or serialization failure returns a null pointer. Free the returned
 * string with [`kglite_free_string`](crate::kglite_free_string); its lifetime
 * is independent of the result handle.
 *
 * # Safety
 * `result` must be null or a live result pointer, and must not be freed during this call.
 */
 const char *kglite_cypher_result_diagnostics_json(const struct KgliteCypherResult *result);

/**
 * Return the number of rows in the result. Useful for callers
 * that want to size buffers before requesting the JSON blob.
 *
 * # Safety
 *
 * `result` must be null or a live pointer returned by a kglite query
 * function. It must not be freed while this call is running.
 */
 uintptr_t kglite_cypher_result_row_count(const struct KgliteCypherResult *result);

/**
 * Free a result handle. Idempotent on null (no-op).
 *
 * # Safety
 *
 * `result` must be either null or a valid pointer previously
 * returned by [`kglite_session_execute_read`](crate::kglite_session_execute_read)
 * or [`kglite_session_execute_mut`](crate::kglite_session_execute_mut)
 * and not yet freed.
 */
 void kglite_cypher_result_free(struct KgliteCypherResult *result);

/**
 * Install a declarative schema on the session's graph.
 *
 * `schema_json` is a JSON object in the one schema dialect kglite speaks —
 * the same one the Python wheel's `define_schema` takes, parsed by the same
 * core function:
 *
 * ```json
 * {
 *   "nodes": {
 *     "Person": {
 *       "required":       ["id", "name"],
 *       "optional":       ["email"],
 *       "types":          {"id": "integer", "name": "string"},
 *       "primary_key":    "id",
 *       "unique":         [["email"]],
 *       "layer":          "managed",
 *       "auto_timestamp": true
 *     }
 *   },
 *   "connections": {
 *     "KNOWS": {
 *       "source":              "Person",
 *       "target":              "Person",
 *       "cardinality":         "many-to-many",
 *       "required_properties": ["since"],
 *       "property_types":      {"since": "integer"}
 *     }
 *   }
 * }
 * ```
 *
 * `source` and `target` are the only mandatory keys anywhere; an absent
 * `nodes` or `connections` section is a no-op, so a document may declare
 * either half alone.
 *
 * `mode` (may be null) is `"merge"` or `"replace"`; null means `"merge"`.
 * **Merge** scopes the declaration to the types the document names — every
 * other type keeps its constraints. **Replace** makes this document the whole
 * schema, so every type it does not name *stops being enforced*. The Python
 * wrapper emits a warning naming each constraint a replace withdraws; C has no
 * warning channel, so pass `"replace"` only when withdrawing is the intent.
 *
 * Installing a schema installs the UNIQUE / NODE KEY constraints it declares,
 * so the call fails when data already in the graph violates one. In that case
 * **nothing changes** — neither the schema nor the indexes — and the caller
 * can fix the data and retry.
 *
 * # Errors
 *
 * - `KGLITE_STATUS_CODE_NULL_POINTER` — `session` or `schema_json` is null.
 * - `KGLITE_STATUS_CODE_INVALID_UTF8` — `schema_json` is not valid UTF-8.
 * - `KGLITE_STATUS_CODE_INVALID_ARGUMENT` — the JSON did not parse, the document is
 *   not in the dialect above, or `mode` is not `"merge"` / `"replace"`; the
 *   message says which.
 * - A constraint status (`KGLITE_STATUS_CODE_CONSTRAINT_VIOLATION` and friends) when
 *   existing data violates a declared constraint; the message names it.
 *
 * **Schemas have no write-ahead-log frame.** On a durable session from
 * [`kglite_open_session`](crate::kglite_open_session) this call returns
 * `KGLITE_STATUS_CODE_DURABILITY_FAILED` and changes nothing. On a session
 * without a log the schema is not durable until
 * [`kglite_session_save`](crate::kglite_session_save).
 *
 * # Safety
 *
 * `session` must be a valid handle from
 * [`kglite_session_new`](crate::kglite_session_new). `schema_json` must be a
 * null-terminated UTF-8 string; `mode` null or the same. `out_error_msg` must
 * be null or a valid writable slot.
 */

KgliteStatusCode kglite_define_schema(struct KgliteSession *session,
                                      const char *schema_json,
                                      const char *mode,
                                      const char **out_error_msg);

/**
 * Create a new session from a graph handle. The session takes
 * ownership of the graph — the caller MUST NOT call
 * [`kglite_graph_free`](crate::kglite_graph_free) on the handle
 * after this call. Free the session via
 * [`kglite_session_free`] when done.
 *
 * # Arguments
 *
 * - `graph` (in, MOVED on success): graph handle. After a successful
 *   call the pointer is no longer valid for any other use.
 * - `out_session` (out, owned): set to the session handle on
 *   success; caller must free via [`kglite_session_free`].
 *
 * # Errors
 *
 * - `KGLITE_STATUS_CODE_NULL_POINTER` — `graph` or `out_session` is null
 *
 * **The graph handle is consumed only on `Ok`; on any error the caller
 * retains ownership and must still free it** with
 * [`kglite_graph_free`](crate::kglite_graph_free). The move happens after
 * argument validation, so a rejected call leaves the handle exactly as it
 * was — a binding that treats "moved" as unconditional leaks the graph on
 * every failed session open. Unlike the rest of the fallible surface this
 * takes no `out_error_msg`: the sole failure is a null argument, which has
 * no message beyond the code, and the parameter list is frozen for this ABI
 * major version.
 *
 * # Safety
 *
 * `graph` must be a valid `*mut KgliteGraph` previously returned
 * by [`kglite_load_file`](crate::kglite_load_file) and not yet
 * freed or moved into another session. `out_session` must be a
 * valid writable pointer to a `*mut KgliteSession` slot.
 */
 KgliteStatusCode kglite_session_new(struct KgliteGraph *graph, struct KgliteSession **out_session);

/**
 * Run a read-only Cypher query.
 *
 * # Arguments
 *
 * - `session` (in, borrowed): the session.
 * - `query` (in, borrowed): UTF-8 Cypher query, null-terminated.
 * - `params_json` (in, borrowed, may be null): JSON object of
 *   parameter bindings. Pass null or `"{}"` for no params. Integer tokens at
 *   any nesting depth must fit signed 64-bit; decimal/exponent tokens must fit
 *   a finite 64-bit float.
 * - `out_result` (out, owned): on success, set to the result
 *   handle; caller must free via [`kglite_cypher_result_free`].
 * - `out_error_msg` (out, owned, may be null): on failure, set
 *   to the error message; caller must free via
 *   [`kglite_free_string`](crate::kglite_free_string).
 *
 * # Errors
 *
 * Any `KgErrorCode` variant — Cypher syntax / type mismatch /
 * timeout / execution error / node-not-found / argument
 * validation. An unrepresentable numeric parameter returns
 * `KGLITE_STATUS_CODE_INVALID_ARGUMENT`; when `out_error_msg` is non-null, its
 * owned message identifies the nested parameter path. The caller frees that
 * message with [`kglite_free_string`](crate::kglite_free_string).
 *
 * # Safety
 *
 * `session` must be valid. `query` and (if non-null) `params_json`
 * must be null-terminated UTF-8 strings.
 */

KgliteStatusCode kglite_session_execute_read(const struct KgliteSession *session,
                                             const char *query,
                                             const char *params_json,
                                             struct KgliteCypherResult **out_result,
                                             const char **out_error_msg);

/**
 * Run a read-only Cypher query with execution options. Same as
 * [`kglite_session_execute_read`], plus:
 *
 * - `timeout_ms`: past this wall-clock budget the query returns
 *   `CypherTimeout`. `0` = no deadline.
 * - `max_work_units`: work budget for the query, **not** a result-row cap.
 *   It is charged against intermediate rows, retained collection items and
 *   scan work — every quantity the executor holds or walks on the way to an
 *   answer — so the count can far exceed the rows returned. Exceeding it
 *   fails the query with an error; nothing is ever silently truncated to it.
 *   Add a `LIMIT` clause to bound output. `0` = no explicit budget.
 *
 * # Safety
 *
 * Same as [`kglite_session_execute_read`].
 */

KgliteStatusCode kglite_session_execute_read_opts(const struct KgliteSession *session,
                                                  const char *query,
                                                  const char *params_json,
                                                  uint64_t timeout_ms,
                                                  uint64_t max_work_units,
                                                  struct KgliteCypherResult **out_result,
                                                  const char **out_error_msg);

/**
 * Run a mutating Cypher query. Same shape as
 * [`kglite_session_execute_read`] but accepts CREATE / SET /
 * DELETE / REMOVE / MERGE statements. The session's underlying
 * graph is auto-committed after a successful execute; use
 * [`kglite_session_begin`](crate::kglite_session_begin) for a multi-statement
 * transaction.
 *
 * # Safety
 *
 * Same as [`kglite_session_execute_read`] except `session` is
 * declared as `*mut` (the call mutates the session's interior
 * graph via commit-swap).
 */

KgliteStatusCode kglite_session_execute_mut(struct KgliteSession *session,
                                            const char *query,
                                            const char *params_json,
                                            struct KgliteCypherResult **out_result,
                                            const char **out_error_msg);

/**
 * Run a mutating query with the same timeout and work-budget semantics as
 * [`kglite_session_execute_read_opts`] — `max_work_units` is a work budget
 * that errors when exceeded, not a result-row cap. A budget failure rolls
 * back the complete statement. `0` disables the corresponding option.
 *
 * # Safety
 *
 * Same as [`kglite_session_execute_mut`].
 */

KgliteStatusCode kglite_session_execute_mut_opts(struct KgliteSession *session,
                                                 const char *query,
                                                 const char *params_json,
                                                 uint64_t timeout_ms,
                                                 uint64_t max_work_units,
                                                 struct KgliteCypherResult **out_result,
                                                 const char **out_error_msg);

/**
 * [`kglite_session_execute_read`] with a [`KgliteExecuteOptions`] block:
 * timeout, work budget and a result-row cap that truncates with a report
 * rather than failing. `options` may be null (no limits). A block whose
 * `struct_size` is smaller than its first field is
 * `KGLITE_STATUS_CODE_INVALID_ARGUMENT`.
 *
 * # Safety
 *
 * As [`kglite_session_execute_read`]; `options` null or a valid pointer to at
 * least `options->struct_size` readable bytes.
 */

KgliteStatusCode kglite_session_execute_read_ex(const struct KgliteSession *session,
                                                const char *query,
                                                const char *params_json,
                                                const struct KgliteExecuteOptions *options,
                                                struct KgliteCypherResult **out_result,
                                                const char **out_error_msg);

/**
 * [`kglite_session_execute_mut`] with a [`KgliteExecuteOptions`] block. The
 * row cap bounds only the rows the trailing `RETURN` reports; every write
 * still happens. On a session opened by
 * [`kglite_open_session`](crate::kglite_open_session) the statement is
 * write-ahead logged at the session's durability level, and a read-only or
 * closed session refuses it (`KGLITE_STATUS_CODE_READ_ONLY` for the former).
 *
 * # Safety
 *
 * As [`kglite_session_execute_mut`]; `options` as for
 * [`kglite_session_execute_read_ex`].
 */

KgliteStatusCode kglite_session_execute_mut_ex(struct KgliteSession *session,
                                               const char *query,
                                               const char *params_json,
                                               const struct KgliteExecuteOptions *options,
                                               struct KgliteCypherResult **out_result,
                                               const char **out_error_msg);

/**
 * Run several read-only Cypher queries against a single consistent
 * snapshot, in one lock acquisition.
 *
 * `queries_json` is a JSON array of objects, each `{"query": "...",
 * "params": {...}}` (the `params` key is optional). Every query sees
 * the same snapshot, taken once up front — cheaper and more consistent
 * than N separate [`kglite_session_execute_read`] calls when a binding
 * issues many small reads. Each `params` object follows the exact numeric
 * admission and owned-error-message contract of
 * [`kglite_session_execute_read`]; its message also identifies the batch
 * entry.
 *
 * On success `out_results_json` is set to an owned JSON string: an
 * array of `{"columns": [...], "rows": [{...}], "diagnostics": {...}}` objects, one per input
 * query in order, with the same natural-value encoding as
 * [`kglite_cypher_result_rows_json`]. Free it with
 * [`kglite_free_string`](crate::kglite_free_string).
 *
 * The batch aborts on the first failing query: `out_results_json` is
 * set to null and the status code / `out_error_msg` describe that
 * query's failure.
 *
 * # Safety
 *
 * `session` must be valid; `queries_json` a null-terminated UTF-8 JSON
 * array; `out_results_json` a valid writable `*const c_char` slot;
 * `out_error_msg` null or a valid writable slot.
 */

KgliteStatusCode kglite_session_execute_read_batch(const struct KgliteSession *session,
                                                   const char *queries_json,
                                                   const char **out_results_json,
                                                   const char **out_error_msg);

/**
 * Run several mutating Cypher queries in a single transaction — one
 * `begin`, N executes (each sees the previous query's writes), a single
 * `commit`. The batch is **atomic**: if any query fails, the
 * transaction is dropped uncommitted and none of the batch's mutations
 * reach the graph.
 *
 * `queries_json` / `out_results_json` have the same shape as
 * [`kglite_session_execute_read_batch`]. On failure `out_results_json`
 * is null and the status / `out_error_msg` describe the failing query.
 *
 * # Safety
 *
 * Same as [`kglite_session_execute_read_batch`] except `session` is
 * `*mut` (the call mutates the session's interior graph via
 * commit-swap).
 */

KgliteStatusCode kglite_session_execute_mut_batch(struct KgliteSession *session,
                                                  const char *queries_json,
                                                  const char **out_results_json,
                                                  const char **out_error_msg);

/**
 * Bulk-create edges addressed by **stable node id + type**, bypassing
 * Cypher — the fast ingest path for bindings loading many edges.
 *
 * `edges_json` is a JSON array of objects:
 * `{"src_id": <id>, "src_type": "Person", "dst_id": <id>,
 *   "dst_type": "Company", "type": "WORKS_AT", "props": {...}}`
 * (`props` optional). `src_id`/`dst_id` are the nodes' stable ids (the
 * same value `n.id` returns), not internal indices. Runs in one
 * transaction: the whole batch commits together, or — on error — none
 * of it lands. Endpoints must already exist; an edge whose source or
 * target id isn't found for its declared type is skipped and counted.
 * A batch that would leave a relationship violating a declared
 * relationship constraint (`IS NOT NULL`, `IS :: <type>`) is refused
 * whole with `KgliteStatusCode::ConstraintViolation`.
 *
 * On success `out_report_json` is set to an owned JSON object
 * `{"connections_created": N, "connections_updated": U,
 * "skipped_missing_endpoint": M, "warnings": [...]}`, where
 * `connections_updated` counts specs that met an existing edge of the same
 * type between the same endpoints and merged their properties into it, and
 * `warnings` lists advisories about the edges written (such as edges whose
 * validity interval is empty under a `half_open` declaration; empty when
 * there are none); free it with
 * [`kglite_free_string`](crate::kglite_free_string).
 *
 * This wraps the shared core primitive
 * [`add_edges_from_specs`](kglite::api::mutation::add_edges_from_specs) —
 * the same engine the Python `add_connections` DataFrame path uses.
 *
 * # Safety
 *
 * `session` must be valid; `edges_json` a null-terminated UTF-8 JSON
 * array; `out_report_json` a valid writable `*const c_char` slot;
 * `out_error_msg` null or a valid writable slot.
 */

KgliteStatusCode kglite_create_edges_batch(struct KgliteSession *session,
                                           const char *edges_json,
                                           const char **out_report_json,
                                           const char **out_error_msg);

/**
 * Checkpoint a session's graph to `path` — the save half of the
 * open / mutate / save cycle.
 *
 * [`kglite_session_new`] takes ownership of the graph handle, so a graph
 * mutated through
 * [`kglite_session_execute_mut`](crate::kglite_session_execute_mut) can only
 * be persisted from the session that now holds it; this is that call.
 * [`kglite_save_graph`](crate::kglite_save_graph) remains the entry point
 * for a graph handle that has *not* been moved into a session.
 *
 * **The lease contract: a caller that saves must hold the writer lease
 * across the whole open / mutate / save interval, not merely at this call.**
 * Take it with
 * [`kglite_writer_lease_acquire`](crate::kglite_writer_lease_acquire) before
 * opening, free it after saving. Two processes that both open one path, both
 * mutate, and both save each write a complete snapshot and the later one
 * wins outright and silently — locking only at save time is already too late
 * to notice. Read-only sessions take no lease.
 *
 * The save writes through the session's own graph, so it never copies the
 * graph to checkpoint it, and it is serialized against concurrent
 * `execute_mut` calls on the same session: the file is a consistent
 * point-in-time image. Readers holding a result from before the save are
 * unaffected.
 *
 * `fsync` != 0 is the durable default: atomic temp+rename plus a file and
 * parent-directory flush, so the checkpoint survives power loss. `fsync` ==
 * 0 is the fast, **non-durable** opt-out — still never a torn file, but the
 * bytes may not survive an OS crash. The storage mode is written from the
 * graph being saved, so reopening with
 * [`kglite_open_or_create_graph_in_mode`](crate::kglite_open_or_create_graph_in_mode)
 * and a null mode brings the graph back in the mode it was saved in.
 *
 * # Errors
 *
 * - `KGLITE_STATUS_CODE_NULL_POINTER` — `session` or `path` is null
 * - `KGLITE_STATUS_CODE_INVALID_UTF8` — `path` isn't valid UTF-8
 * - `KGLITE_STATUS_CODE_FILE_IO` — the write failed
 *
 * # Safety
 *
 * `session` must be a valid handle from [`kglite_session_new`], not yet
 * freed; `path` a null-terminated UTF-8 string; `out_error_msg` null or a
 * valid writable slot.
 */

KgliteStatusCode kglite_session_save(struct KgliteSession *session,
                                     const char *path,
                                     uint8_t fsync,
                                     const char **out_error_msg);

/**
 * Write a consistent single-file `.kgl` backup of a session's published graph
 * to `dest` while writers keep committing.
 *
 * Unlike [`kglite_session_save`](crate::kglite_session_save), a backup is an
 * independent copy: it takes no writer lease, creates no `-wal` sidecar, and
 * does not touch the session's checkpoint. Memory and mapped graphs are
 * supported; a disk-mode graph is refused. An existing `dest` is replaced
 * atomically.
 *
 * `live_path` (nullable) is the file the graph was opened from, when the
 * caller has one. A session cannot know it, so pass it to have a backup over
 * the live file refused; a durable session also detects its own log sidecar.
 *
 * On success `out_report_json` is an owned JSON object: `path`, `bytes`,
 * `nodes`, `relationships`, `graph_version`, `lsn` (null for a session
 * without a write-ahead log), `lock_hold_ms`, `elapsed_ms`,
 * `prepared_copy` (true when the snapshot needed a private prepared copy
 * first). Free it with
 * [`kglite_free_string`](crate::kglite_free_string). On failure it is null.
 *
 * # Errors
 *
 * - `KGLITE_STATUS_CODE_NULL_POINTER` — `session`, `dest` or `out_report_json` is null
 * - `KGLITE_STATUS_CODE_INVALID_UTF8` — `dest` or `live_path` isn't valid UTF-8
 * - `KGLITE_STATUS_CODE_FILE_IO` — the write failed, or the backup was
 *   refused (destination aliases the live checkpoint, disk-mode graph);
 *   the message says which
 *
 * # Safety
 *
 * `session` must be a valid handle from [`kglite_session_new`], not yet
 * freed; `dest` a null-terminated UTF-8 string; `live_path` null or a
 * null-terminated UTF-8 string; `out_report_json` a valid writable slot;
 * `out_error_msg` null or a valid writable slot.
 */

KgliteStatusCode kglite_session_backup(const struct KgliteSession *session,
                                       const char *dest,
                                       const char *live_path,
                                       const char **out_report_json,
                                       const char **out_error_msg);

/**
 * Choose how this session's JSON results spell typed values.
 *
 * With [`KgliteResultEncoding::Natural`] (the default for a new session)
 * results are the JSON every earlier release produced. With
 * [`KgliteResultEncoding::Tagged`] a date, datetime, duration, point and every
 * non-finite float render as the tagged objects documented on that enum, at
 * any depth, including node and relationship properties. They are the tags a
 * query parameter accepts, so a result cell read back and bound again is
 * unchanged. The setting governs
 * [`kglite_cypher_result_rows_json`](crate::kglite_cypher_result_rows_json)
 * of results produced afterwards and the rows of the batch-execute results; a
 * result already returned keeps the encoding it was created with. Ids,
 * strings, integers, finite floats (including `-0.0`) and booleans are
 * unaffected.
 *
 * Returns `KGLITE_STATUS_CODE_INVALID_ARGUMENT` for a value that is not a
 * `KgliteResultEncoding`, and `KGLITE_STATUS_CODE_NULL_POINTER` for a null
 * `session`.
 *
 * # Safety
 *
 * `session` must be a valid session pointer not yet freed.
 */

KgliteStatusCode kglite_session_set_result_encoding(const struct KgliteSession *session,
                                                    uint32_t encoding);

/**
 * Free a session handle. Idempotent on null (no-op).
 *
 * # Safety
 *
 * `session` must be either null or a valid pointer previously
 * returned by [`kglite_session_new`] and not yet freed.
 */
 void kglite_session_free(struct KgliteSession *session);

/**
 * Return the canonical human-readable name of a status code (e.g.
 * `"CypherSyntax"`, `"NodeNotFound"`, `"InvalidUtf8"`).
 *
 * The returned string is OWNED by the caller and must be freed
 * via [`kglite_free_string`](crate::kglite_free_string). Returns
 * null on `Ok` (no error to name).
 */
 const char *kglite_status_code_name(KgliteStatusCode code);

/**
 * Return the canonical name of a status code as a **static** string — the
 * allocation-free companion to [`kglite_status_code_name`].
 *
 * Same text (`"CypherSyntax"`, `"NodeNotFound"`, `"InvalidUtf8"`, …) and the
 * same null on `Ok`, but the pointer is a `'static` constant in the library's
 * own read-only data rather than a fresh heap copy.
 *
 * **Do NOT free the returned pointer.** Handing it to
 * [`kglite_free_string`](crate::kglite_free_string) is undefined behaviour —
 * it is not allocator-owned memory. That is the whole difference between the
 * two functions, so pick one per call site and do not mix them:
 * [`kglite_status_code_name`] for a caller that would rather free one uniform
 * kind of string, this one for a binding that names a code on every error
 * (the common case — the name goes straight into the exception it raises),
 * which then skips the allocate/copy/free round trip entirely.
 *
 * Added rather than changing [`kglite_status_code_name`] in place: that
 * function shipped with owned-string semantics and this ABI is additive-only
 * within a major version, so silently flipping who frees it would turn a
 * correct caller into a double-free.
 *
 * The table is exhaustive over `KgliteStatusCode` by construction (no
 * wildcard arm), so a newly added status code is a compile error here rather
 * than a silently unnamed one.
 */
 const char *kglite_status_code_name_static(KgliteStatusCode code);

/**
 * Return the Neo4j wire status code for a status code (e.g.
 * `"Neo.ClientError.Statement.SyntaxError"`). Useful for bindings
 * implementing the Neo4j Bolt wire protocol or compatible HTTP
 * APIs.
 *
 * The returned string is OWNED by the caller and must be freed
 * via [`kglite_free_string`](crate::kglite_free_string). Returns
 * null on `Ok` or on C-ABI-only error codes that have no Neo4j
 * counterpart (`InvalidUtf8`, `NullPointer`).
 */
 const char *kglite_status_code_neo4j_status(KgliteStatusCode code);

/**
 * Return the HTTP status code mapping for a status code (e.g.
 * 400 for `CypherSyntax`, 404 for `NodeNotFound`, 500 for
 * `Internal`). Useful for REST/gRPC bindings.
 *
 * Returns 0 for `Ok`; the C-ABI-only codes answer directly (`InvalidUtf8`
 * and `NullPointer` = 400, bad request from the caller). `WriterLeaseHeld`
 * delegates to core (409, retriable as-is, like `TransactionConflict`).
 */
 uint16_t kglite_status_code_http_status(KgliteStatusCode code);

/**
 * Free a string previously returned by any `kglite_*` function.
 *
 * # Safety
 *
 * `s` must be either null or a pointer previously returned
 * by a `kglite_*` function (these all flow through
 * [`alloc_c_string`]). Calling twice on the same pointer is UB.
 * Calling with a pointer to a string allocated by the C caller's
 * own `malloc` is UB.
 *
 * Passing null is safe (treated as a no-op).
 *
 * # Examples
 *
 * ```c
 * const char* col_json = kglite_cypher_result_columns_json(result);
 * printf("%s\n", col_json);
 * kglite_free_string(col_json);
 * ```
 */
 void kglite_free_string(const char *s);

/**
 * Build a BM25 lexical index over `node_type`'s `property`, for keyword
 * ranking in Cypher.
 *
 * Wraps [`kglite::api::text_indexes::build_text_index`]. Opt-in and explicit.
 * The index does not follow later writes eagerly: it records them and folds
 * them in at query time while the outstanding delta stays under the default
 * auto-refresh limit, and once past it a rebuild — this call again — is the
 * route back. `SHOW INDEXES` reports the delta. Deleting a node prunes its
 * document immediately (a freed node slot is reused, and an orphaned document
 * would be inherited by its next owner); `vacuum` renumbers every node and
 * therefore drops text indexes wholesale. Strings and lists containing only
 * strings/nulls each form one document; list members are space-separated and
 * null members ignored. Empty strings and empty/all-null lists are empty
 * documents. Absent values, other types, or any non-text/non-null list member
 * skip the whole document and count in the report. Fields use the same alias
 * resolution a `MATCH` filter uses.
 *
 * The auto-refresh limit is not a parameter here: this signature is published
 * and additive-only within the ABI major, so the C route takes the default and
 * a future symbol carries the override if one is ever asked for.
 *
 * On success `out_report_json` is an owned JSON object
 * `{"indexed": N, "skipped": S, "terms": T}`; free it with
 * [`kglite_free_string`](crate::kglite_free_string).
 *
 * # Errors
 *
 * - `KGLITE_STATUS_CODE_NULL_POINTER` — `session`, `node_type`, `property`, or
 *   `out_report_json` is null.
 * - `KGLITE_STATUS_CODE_INVALID_UTF8` — a string argument is not valid UTF-8.
 * - `KGLITE_STATUS_CODE_INVALID_ARGUMENT` — the node type is unknown, the graph is
 *   disk-backed (the index is heap-resident, so disk mode refuses), or the
 *   type has nodes and none of them carries a string for `property`; the
 *   message explains which.
 *
 * # Safety
 *
 * `session` must be a valid handle from
 * [`kglite_session_new`](crate::kglite_session_new). `node_type` and
 * `property` must be null-terminated UTF-8 strings. `out_report_json` must be
 * a valid writable slot; `out_error_msg` null or a valid writable slot.
 */

KgliteStatusCode kglite_session_build_text_index(struct KgliteSession *session,
                                                 const char *node_type,
                                                 const char *property,
                                                 const char **out_report_json,
                                                 const char **out_error_msg);

/**
 * Begin an explicit transaction on `session`.
 *
 * A read-write transaction (`read_only` false) is refused with
 * `KGLITE_STATUS_CODE_READ_ONLY` on a session opened read-only, and with
 * `KGLITE_STATUS_CODE_INVALID_ARGUMENT` on a closed one. A read-only
 * transaction reads one fixed snapshot and refuses every write with
 * `KGLITE_STATUS_CODE_READ_ONLY`.
 *
 * # Arguments
 *
 * - `session` (in): a session handle that outlives the transaction.
 * - `read_only` (in): whether the transaction may write.
 * - `out_tx` (out, owned): the transaction handle; free it with
 *   [`kglite_tx_free`]. Null on error.
 * - `out_error_msg` (out, owned, nullable): error message; free with
 *   [`kglite_free_string`](crate::kglite_free_string).
 *
 * # Thread safety
 *
 * A transaction is single-threaded: do not call its functions concurrently.
 * The session stays usable from other threads, and other transactions
 * begun on it run independently.
 *
 * # Safety
 *
 * `session` a valid live session handle; `out_tx` a valid writable slot;
 * `out_error_msg` null or a valid writable slot.
 */

KgliteStatusCode kglite_session_begin(struct KgliteSession *session,
                                      bool read_only,
                                      struct KgliteTx **out_tx,
                                      const char **out_error_msg);

/**
 * Run one statement inside `tx`.
 *
 * Reads and writes both see this transaction's earlier writes and nothing
 * that other writers committed since [`kglite_session_begin`]. The writes
 * stay private until [`kglite_tx_commit`]. A failed statement is rolled
 * back on its own; the transaction stays open. `options` is as for
 * [`kglite_session_execute_read_ex`](crate::kglite_session_execute_read_ex);
 * null means no limits.
 *
 * # Errors
 *
 * - `KGLITE_STATUS_CODE_READ_ONLY`: a write in a read-only transaction.
 * - `KGLITE_STATUS_CODE_INVALID_ARGUMENT`: the transaction was already
 *   committed or rolled back.
 *
 * # Safety
 *
 * `tx` a live handle from [`kglite_session_begin`], not used concurrently;
 * `query` a NUL-terminated UTF-8 string; `params_json` null or one;
 * `options` null or readable for `options->struct_size` bytes; the out
 * slots valid and writable (`out_error_msg` may be null).
 */

KgliteStatusCode kglite_tx_execute(struct KgliteTx *tx,
                                   const char *query,
                                   const char *params_json,
                                   const struct KgliteExecuteOptions *options,
                                   struct KgliteCypherResult **out_result,
                                   const char **out_error_msg);

/**
 * Commit `tx`, publishing its writes atomically, then finish it.
 *
 * If another writer committed since [`kglite_session_begin`], nothing is
 * applied and the status is `KGLITE_STATUS_CODE_TRANSACTION_CONFLICT`:
 * begin a new transaction and redo the work. On a durable session the commit
 * is logged before it is published; a log failure is
 * `KGLITE_STATUS_CODE_DURABILITY_FAILED` and nothing is applied. In every
 * case the transaction is finished afterwards; only
 * [`kglite_tx_free`] remains to be called. Committing a read-only or
 * write-free transaction succeeds and changes nothing.
 *
 * # Safety
 *
 * `tx` a live handle, not used concurrently; `out_error_msg` null or a valid
 * writable slot.
 */
 KgliteStatusCode kglite_tx_commit(struct KgliteTx *tx, const char **out_error_msg);

/**
 * Discard `tx` and its writes, then finish it. Rolling back a finished
 * transaction is a no-op that returns `KGLITE_STATUS_CODE_OK`.
 *
 * # Safety
 *
 * `tx` a live handle, not used concurrently.
 */
 KgliteStatusCode kglite_tx_rollback(struct KgliteTx *tx);

/**
 * Free a transaction handle. A transaction still open is rolled back; free
 * never commits. Null is a no-op. Free every transaction before freeing or
 * closing its session.
 *
 * # Safety
 *
 * `tx` null or a handle from [`kglite_session_begin`] not yet freed, not
 * used concurrently.
 */
 void kglite_tx_free(struct KgliteTx *tx);

#endif  /* KGLITE_H_INCLUDED */
